    distanceFromCentralColor=min(abs(central-sampler)*distanceNormalizationFactor,1.);
    gaussianWeight=.09*(1.-distanceFromCentralColor);
    gaussianWeightTotal+=gaussianWeight;
    sum+=sampler*gaussianWeight;
    
    sampler=texture2D(uSampler,blurCoordinates11).g;
    distanceFromCentralColor=min(abs(central-sampler)*distanceNormalizationFactor,1.);
    gaussianWeight=.09*(1.-distanceFromCentralColor);
    gaussianWeightTotal+=gaussianWeight;
    sum+=sampler*gaussianWeight;
    
    sampler=texture2D(uSampler,blurCoordinates12).g;
    distanceFromCentralColor=min(abs(central-sampler)*distanceNormalizationFactor,1.);
    gaussianWeight=.1*(1.-distanceFromCentralColor);
    gaussianWeightTotal+=gaussianWeight;
    sum+=sampler*gaussianWeight;
    
    sampler=texture2D(uSampler,blurCoordinates13).g;
    distanceFromCentralColor=min(abs(central-sampler)*distanceNormalizationFactor,1.);
    gaussianWeight=.1*(1.-distanceFromCentralColor);
